sealed class Favorite {
  const Favorite();

  factory Favorite.fromJson(Object? json) {
    final fields = json as JsonMap;
    return switch (fields['kind']) {
      'movie' => FavoriteMovie.fromJson(fields),
      'show' => FavoriteShow.fromJson(fields),
      'showSeason' => FavoriteShowSeason.fromJson(fields),
      'episode' => FavoriteEpisode.fromJson(fields),
      final tag => throw FormatException('Unknown Favorite tag', tag),
    };
  }

  JsonMap toJson();
}

